import {materials} from '../../core/index.js';
import {FACE} from '../../modeling/parts.js';
import {THREE,roundedRect,mesh,circleHole,extrude,annulus,box,plate} from './geometry.js';
import {spec} from './dimensions.js';
const white=()=>materials.plastic(0xeceee6,{roughness:.8});
function frontOutline(){const s=new THREE.Shape();s.moveTo(-8,-16);s.lineTo(-5.15,-16);s.lineTo(-5.15,-9.7);s.lineTo(5.15,-9.7);s.lineTo(5.15,-16);s.lineTo(8,-16);s.absarc(8,-12,4,-Math.PI/2,0,false);s.lineTo(12,12);s.absarc(8,12,4,0,Math.PI/2,false);s.lineTo(7,16);s.lineTo(7,-.8);s.lineTo(-7,-.8);s.lineTo(-7,16);s.lineTo(-8,16);s.absarc(-8,12,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-12);s.absarc(-8,-12,4,Math.PI,Math.PI*1.5,false);s.closePath();for(const[x,y]of spec.mounting.centres)circleHole(s,x,y,spec.mounting.boreRadiusMm);return s;}
function leftWall(){const s=new THREE.Shape();s.moveTo(-7,16);s.lineTo(-8,16);s.absarc(-8,12,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-12);s.absarc(-8,-12,4,Math.PI,Math.PI*1.5,false);s.lineTo(-5.15,-16);s.lineTo(-5.15,-14.9);s.lineTo(-8,-14.9);s.absarc(-8,-12,2.9,-Math.PI/2,-Math.PI,true);s.lineTo(-10.9,12);s.absarc(-8,12,2.9,Math.PI,Math.PI/2,true);s.lineTo(-7,14.9);s.closePath();return s;}
function relief(parent){const frame=new THREE.Group();frame.position.set(0,-10,-4.3);frame.quaternion.copy(FACE.back);frame.name='U011 own visible unpainted moulded M5 relief;photo silhouette estimate';parent.add(frame);const m=white(),glyphs=[];
 for(const[name,points]of[['M',[[-4.6,-2],[-4.6,2],[-4.1,2],[-2.55,.3],[-1,2],[-.5,2],[-.5,-2],[-1,-2],[-1,1.2],[-2.55,-.45],[-4.1,1.2],[-4.1,-2]]],['5',[[.4,2],[4.5,2],[4.5,1.5],[.95,1.5],[.95,.35],[3.3,.35],[4.2,-.15],[4.5,-.7],[4.5,-1.4],[4.05,-2],[.4,-2],[.4,-1.5],[3.75,-1.5],[3.95,-1.15],[3.95,-.8],[3.7,-.35],[3.15,-.15],[.4,-.15]]]])glyphs.push(mesh(frame,extrude(new THREE.Shape(points.map(p=>new THREE.Vector2(...p))),.1),m,[0,0,0],'U011 physical moulded '+name+' glyph;no bitmap ink'));
 return{frame,glyphs};}
export function shell(host){const m=white(),back=roundedRect(24,32,4);for(const[x,y]of spec.mounting.centres)circleHole(back,x,y,2.55);circleHole(back,0,-4,1.65);const rear=mesh(host.body,extrude(back,1),m,[0,0,-4.3],'U011 own closed rear plate;actual mounting and screw openings'),front=mesh(host.body,extrude(frontOutline(),1),m,[0,0,3.3],'U011 own closed front plate with genuine boundary IO/Grove notches'),s=leftWall(),mirrored=new THREE.Shape(s.getPoints(64).map(p=>new THREE.Vector2(-p.x,p.y))),sides=[mesh(host.body,extrude(s,6.6),m,[0,0,-3.3],'U011 closed left perimeter wall with open connector ends'),mesh(host.body,extrude(mirrored,6.6),m,[0,0,-3.3],'U011 closed right perimeter wall with open connector ends')];
 const lowerFloor=box(host.body,[10.3,1.1,1.7],[0,-15.45,-2.45],m,'U011 actual lower white casing bridge beneath Grove floor'),lowerLip=box(host.body,[10.3,1.1,.7],[0,-15.45,3.95],m,'U011 white upper Grove mouth lip'),upperFloor=box(host.body,[14,1.1,3.65],[0,15.45,-1.475],m,'U011 white IO mouth floor;actual air remains above');
 const hood=plate(host.body,16,16.8,.7,1,[0,7.6,5.7],m,'U011 actual raised blank front hood ceiling;own-photo dimensional estimate'),hoodSides=[];for(const x of[-7.5,7.5])hoodSides.push(box(host.body,[1,16.8,2.4],[x,7.6,4.5],m,'U011 real raised hood side wall'));const hoodLower=box(host.body,[14,1.6,2.4],[0,0,4.5],m,'U011 closed raised hood lower shoulder');
 const bosses=[];for(const[x,y]of spec.mounting.centres)bosses.push(mesh(host.body,annulus(3.25,2.55,6.6),m,[x,y,-3.3],'U011 true through-bore boss;body through air is preserved'));
 const screwBoss=mesh(host.body,annulus(2.1,.85,6.6),m,[0,-4,-3.3],'U011 central fixed screw support with real shaft channel');return{front,rear,sides,lowerFloor,lowerLip,upperFloor,hood,hoodSides,hoodLower,bosses,screwBoss,relief:relief(host.body)};}
export function fixing(host){const metal=materials.metal(0xa9aca3,{roughness:.42}),s=new THREE.Shape();s.absarc(0,0,1.43,0,Math.PI*2,false);const drive=new THREE.Path();for(let i=0;i<6;i++){const a=i*Math.PI/3;i?drive.lineTo(Math.cos(a)*.59,Math.sin(a)*.59):drive.moveTo(Math.cos(a)*.59,Math.sin(a)*.59);}drive.closePath();s.holes.push(drive);const head=mesh(host.body,extrude(s,.6),metal,[0,-4,-4.28],'U011 recessed physical fastening head with true hexagonal drive well'),floor=mesh(host.body,new THREE.CylinderGeometry(.58,.58,.08,32).rotateX(Math.PI/2),materials.plastic(0x41453d),[0,-4,-3.69],'U011 true recessed drive floor'),washer=mesh(host.body,annulus(1.7,.7,.38),metal,[0,-4,-3.68],'U011 screw bearing physically contacts rear support'),shank=mesh(host.body,new THREE.CylinderGeometry(.7,.7,6.2,32).rotateX(Math.PI/2),metal,[0,-4,-.58],'U011 fixed screw shank retained through real boss');return{head,floor,washer,shank};}
